// Map every source item to one shape so the LLM sees comparable evidence:
// { source, source_id, client, project, owner, observed_at, due_date, status, summary, evidence_url }
// Source is detected from the item's fields (Merge appends all seven branches).
// CLIENTS: list your client / project names so records get tagged. Leave empty to let the LLM infer.
const CLIENTS = [];
const win = $('Set reporting window · Last 7 days').first().json;
const clip = (s, n = 600) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, n);
const findClient = (...texts) => {
  const t = texts.join(' ').toLowerCase();
  return CLIENTS.find(c => t.includes(c.toLowerCase())) || null;
};
const header = (j, name) => (j.payload?.headers || []).find(h => h.name?.toLowerCase() === name)?.value;
const plainProp = p => {
  if (!p) return null;
  if (p.title) return p.title.map(t => t.plain_text).join('');
  if (p.rich_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.select) return p.select?.name;
  if (p.status) return p.status?.name;
  if (p.date) return p.date?.start;
  if (p.people) return p.people.map(x => x.name).join(', ');
  return typeof p === 'string' ? p : null;
};

function normalize(j) {
  // Jira issue
  if (j.key && j.fields) {
    const f = j.fields;
    return { source: 'jira', source_id: j.key, project: f.project?.name, owner: f.assignee?.displayName,
      observed_at: f.updated, due_date: f.duedate, status: f.status?.name,
      summary: clip(`${f.summary}. ${f.issuetype?.name || ''} · priority ${f.priority?.name || 'n/a'}`),
      evidence_url: j.self, client: findClient(f.summary, f.project?.name, (f.labels || []).join(' ')) };
  }
  // Gmail message
  if (j.threadId && (j.snippet !== undefined || j.payload)) {
    const subject = j.Subject || header(j, 'subject');
    const from = j.From || header(j, 'from');
    const date = j.internalDate ? new Date(Number(j.internalDate)).toISOString() : (j.Date || header(j, 'date'));
    return { source: 'gmail', source_id: j.id, owner: from, observed_at: date, status: null,
      summary: clip(`${subject || '(no subject)'}: ${j.snippet || j.text || ''}`),
      evidence_url: `https://mail.google.com/mail/u/0/#all/${j.threadId}`, client: findClient(subject, j.snippet, from) };
  }
  // Slack message
  if (j.ts && (j.text !== undefined)) {
    return { source: 'slack', source_id: `${j.channel || j.channel_id || 'channel'}:${j.ts}`, owner: j.user_name || j.user,
      observed_at: new Date(Number(j.ts) * 1000).toISOString(), status: null, summary: clip(j.text),
      evidence_url: j.permalink || null, client: findClient(j.text) };
  }
  // Notion database page (release notes)
  if (j.object === 'page' || (j.properties && j.url?.includes('notion'))) {
    const props = j.properties || {};
    const title = plainProp(Object.values(props).find(p => p?.title)) || j.name;
    return { source: 'notion', source_id: j.id, owner: plainProp(props.Owner), observed_at: j.last_edited_time,
      due_date: plainProp(props['Release date'] || props.Date), status: plainProp(props.Status),
      summary: clip(`${title}. ${Object.entries(props).map(([k, v]) => `${k}: ${plainProp(v) ?? ''}`).join('; ')}`),
      evidence_url: j.url, client: findClient(title, JSON.stringify(props)) };
  }
  // Google Drive file (PRD / FRD)
  if (j.mimeType && (j.webViewLink || j.name)) {
    return { source: 'drive', source_id: j.id, owner: j.owners?.[0]?.displayName, observed_at: j.modifiedTime,
      status: null, summary: clip(`${j.name} (${j.mimeType.split('.').pop()})`), evidence_url: j.webViewLink,
      client: findClient(j.name) };
  }
  // Read.ai / transcript API meeting
  if (j.title && (j.summary || j.action_items || j.transcript)) {
    const actions = (j.action_items || []).map(a => a.text || a).join('; ');
    return { source: 'meetings', source_id: j.id || j.session_id, owner: j.owner?.name, observed_at: j.start_time || j.created_at,
      status: null, summary: clip(`${j.title}. ${j.summary || ''} Actions: ${actions}`, 900),
      evidence_url: j.report_url || j.url || null, client: findClient(j.title, j.summary) };
  }
  // Google Sheets tracker row (any other flat object)
  const pick = (...keys) => keys.map(k => Object.entries(j).find(([c]) => c.toLowerCase() === k)?.[1]).find(v => v);
  return { source: 'sheets', source_id: `row:${j.row_number ?? '?'}`, project: pick('project', 'program', 'workstream'),
    owner: pick('owner', 'assignee', 'pm'), observed_at: pick('updated', 'last updated', 'date'),
    due_date: pick('due', 'due date', 'eta', 'target date'), status: pick('status', 'health', 'rag'),
    summary: clip(Object.entries(j).map(([k, v]) => `${k}: ${v}`).join('; ')), evidence_url: null,
    client: pick('client', 'account', 'customer') || findClient(JSON.stringify(j)) };
}

const records = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length && !j.error) // skip empty or failed sources
  .map(normalize)
  .map(r => ({ ...r, client: r.client || null, project: r.project || null, owner: r.owner || null,
    due_date: r.due_date || null, observed_at: r.observed_at || null }));

const bySource = records.reduce((a, r) => (a[r.source] = (a[r.source] || 0) + 1, a), {});
return [{ json: { ...win, recordCount: records.length, bySource, records } }];

// Quality gate: parse the LLM's JSON, keep only claims backed by evidence that exists
// in the normalized records, and flag stale or missing data instead of hiding it.
const STALE_DAYS = 14;
const ctx = $('Normalize · Map clients, owners & dates').first().json;
const ids = new Set(ctx.records.map(r => String(r.source_id)));
const raw = String($input.first().json.output ?? $input.first().json.text ?? '');
let data;
try { data = JSON.parse(raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim()); }
catch (e) { const m = raw.match(/\{[\s\S]*\}/); data = m ? JSON.parse(m[0]) : null; }
if (!data) throw new Error('LLM did not return JSON. Check the agent prompt or the model.');

const gaps = [...(data.gaps || [])];
const rejected = [];
const now = new Date(ctx.until);
const ageDays = d => (now - new Date(d)) / 864e5;
function check(kind, list, label) {
  return (list || []).filter(x => {
    const ev = (x.evidence || []).filter(e => ids.has(String(e.source_id)));
    if (!ev.length) { rejected.push(`${kind}: ${label(x)} (no matching source record)`); return false; }
    x.evidence = ev;
    const newest = ev.map(e => e.date).filter(Boolean).sort().pop();
    x.fresh = newest ? ageDays(newest) <= STALE_DAYS : false;
    if (!x.fresh) gaps.push(`${kind} "${label(x)}" relies on evidence older than ${STALE_DAYS} days or undated.`);
    for (const f of ['owner', 'due']) if (f in x && !x[f]) gaps.push(`${kind} "${label(x)}" has no ${f}.`);
    return true;
  });
}
const report = {
  period: data.period || `${ctx.sinceDate} → ${ctx.untilDate}`,
  headline: data.headline || '',
  clients: check('Client', data.clients, x => x.name),
  milestones: check('Milestone', data.milestones, x => `${x.client} · ${x.milestone}`),
  releases: check('Release', data.releases, x => x.feature),
  decisions: check('Decision', data.decisions_needed, x => x.ask),
};
return [{ json: { report, gaps: [...new Set(gaps)], rejected, recordCount: ctx.recordCount, bySource: ctx.bySource,
  generatedAt: new Date().toISOString(), passed: rejected.length === 0 } }];

