<div class="tag">WIB ✳ LEADERSHIP REPORTING AGENT · ${esc(id)}</div><h1>${esc(title)}</h1><p>${esc(sub)} · ${esc(R.period)}</p>${R.headline ? `<div class="callout"><b>Headline:</b> ${esc(R.headline)}</div>` : ''}
${body}${gapBox()}<p class="small">Generated ${esc(generatedAt)} from ${esc(recordCount)} source records (${esc(Object.entries(bySource || {}).map(([k, v]) => `${k} ${v}`).join(' · '))})</p></main></body></html>`;
const out = (report, filename, html, extra = {}) => [{ json: { report, filename, html, ...extra },
  binary: { data: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: filename } } }];
const count = (list, re) => list.filter(x => re.test(x.health || x.status || '')).length;

const C = R.clients, D = R.decisions, M = R.milestones;
const atRisk = C.filter(c => /risk|watch/i.test(c.health));
const body = `<div class="kpis">${kpi(C.length, 'programs')}${kpi(count(C, /on track/i), 'on track')}${kpi(atRisk.length, 'need attention')}${kpi(D.length, 'decisions needed')}</div>
<h2>Needs leadership attention</h2><table><thead><tr><th>Program</th><th>Health</th><th>Blocker</th><th>Proposed next step</th><th>Evidence</th></tr></thead><tbody>${atRisk.map(c => `<tr><td><b>${esc(c.name)}</b><br>${esc(c.program)}</td><td>${pill(c.health)}</td><td>${esc(c.blocker || '—')}</td><td>${esc(c.next || '—')}</td><td>${ev(c.evidence)}</td></tr>`).join('') || '<tr><td colspan="5">Nothing at risk this week.</td></tr>'}</tbody></table>
<h2>Decisions & asks</h2><table><thead><tr><th>Ask</th><th>Owner</th><th>By</th><th>Evidence</th></tr></thead><tbody>${D.map(x => `<tr><td>${esc(x.ask)}</td><td>${esc(x.owner || '—')}</td><td>${esc(x.due || '—')}</td><td>${ev(x.evidence)}</td></tr>`).join('')}</tbody></table>
<h2>Deck outline</h2><ol><li>Headline and portfolio health (${count(C, /on track/i)} on track, ${atRisk.length} need attention)</li><li>Programs at risk: ${atRisk.map(c => esc(c.name)).join(', ') || 'none'}</li><li>Milestones due in the next two weeks (${M.filter(m => m.due && (new Date(m.due) - Date.now()) / 864e5 <= 14 && !/done/i.test(m.status)).length})</li><li>Decisions needed today (${D.length})</li><li>Gaps in the data</li></ol>`;
return out('wsr', 'weekly-status-report.html', page('WSR', 'Weekly status review', 'Leadership summary, asks and deck outline', body));

// Shared report helpers (repeated in each report node because n8n Code nodes can't import).
const { report: R, gaps, rejected, generatedAt, recordCount, bySource, passed } = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const css = `body{font:14px Inter,Arial,sans-serif;background:#F2EFE6;color:#0E0E10;margin:0;padding:32px}main{max-width:1100px;margin:auto}
h1{font-size:40px;margin:.2em 0}h2{margin-top:34px}.tag,.small,th{font:11px 'JetBrains Mono',monospace;letter-spacing:.08em;text-transform:uppercase;color:#5d6263}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.kpi,.card{border:1px solid #D9D8CF;background:#fff8;padding:16px}.kpi b{font-size:28px;display:block}
.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}table{border-collapse:collapse;width:100%;margin:14px 0}td,th{border-bottom:1px solid #ddd;padding:9px;text-align:left;vertical-align:top}
.pill{padding:3px 7px;font:10px 'JetBrains Mono',monospace;background:#E3F7A0}.risk{background:#FFD3C6}.watch{background:#FFF0C6}.ev{font:10px 'JetBrains Mono',monospace;color:#747B7C}
.callout{padding:14px 16px;background:#ECEEE1;border-left:4px solid #D4FF3A;margin:12px 0}.gaps{border-left-color:#FF5B2E}.bar{height:6px;background:#D4FF3A}
.gantt{display:grid;gap:4px;margin:14px 0}.grow{display:grid;grid-template-columns:260px 1fr;align-items:center;gap:8px}.track{position:relative;height:22px;background:#E8E7DE}
.seg{position:absolute;top:3px;height:16px;background:#0E0E10;color:#D4FF3A;font:10px 'JetBrains Mono',monospace;padding:0 4px;white-space:nowrap;overflow:hidden}
.seg.risk{background:#FF5B2E;color:#fff}.seg.done{background:#9aa08f}.today{position:absolute;top:0;bottom:0;width:2px;background:#FF5B2E}
@media(max-width:700px){.kpis,.grid{grid-template-columns:1fr}.grow{grid-template-columns:1fr}body{padding:16px}}`;
const cls = h => /risk|late|blocked/i.test(h) ? 'risk' : /watch/i.test(h) ? 'watch' : /done|shipped/i.test(h) ? 'done' : '';
const pill = h => `<span class="pill ${cls(h)}">${esc(h || 'n/a')}</span>`;
const ev = list => (list || []).map(e => e.url ? `<a class="ev" href="${esc(e.url)}">${esc(e.source)} · ${esc(e.source_id)} · ${esc(e.date)}</a>` : `<span class="ev">${esc(e.source)} · ${esc(e.source_id)} · ${esc(e.date)}</span>`).join('<br>');
const kpi = (n, l) => `<div class="kpi"><b>${esc(n)}</b><span class="small">${esc(l)}</span></div>`;
const gapBox = () => (gaps.length || rejected.length) ? `<h2>Gaps & checks</h2><div class="callout gaps">${gaps.map(g => `<div>· ${esc(g)}</div>`).join('')}${rejected.map(g => `<div>✕ Dropped, unsupported: ${esc(g)}</div>`).join('')}</div>` : `<div class="callout">Quality gate passed: every claim cites a source record.</div>`;
const page = (id, title, sub, body) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${css}</style></head><body><main>
<div class="tag">WIB ✳ LEADERSHIP REPORTING AGENT · ${esc(id)}</div><h1>${esc(title)}</h1><p>${esc(sub)} · ${esc(R.period)}</p>${R.headline ? `<div class="callout"><b>Headline:</b> ${esc(R.headline)}</div>` : ''}
${body}${gapBox()}<p class="small">Generated ${esc(generatedAt)} from ${esc(recordCount)} source records (${esc(Object.entries(bySource || {}).map(([k, v]) => `${k} ${v}`).join(' · '))})</p></main></body></html>`;
const out = (report, filename, html, extra = {}) => [{ json: { report, filename, html, ...extra },
  binary: { data: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: filename } } }];
const count = (list, re) => list.filter(x => re.test(x.health || x.status || '')).length;

const Rel = R.releases;
const stages = ['SHIPPED', 'READY', 'IN PROGRESS', 'BLOCKED'];
const funnel = stages.map(s => kpi(Rel.filter(r => (r.status || '').toUpperCase() === s).length, s.toLowerCase())).join('');
const byClient = [...new Set(Rel.map(r => r.client || 'Platform'))].map(c => { const rs = Rel.filter(r => (r.client || 'Platform') === c);
  return `<article class="card"><div class="tag">${esc(c)}</div>${rs.map(r => `<p>${pill(r.status)} <b>${esc(r.feature)}</b> <span class="small">${esc(r.date || '')}</span><br>${ev(r.evidence)}</p>`).join('')}</article>`; }).join('');
const body = `<h2>Demand to delivery</h2><div class="kpis">${funnel}</div><h2>Feature readiness by account</h2><div class="grid">${byClient || '<p>No release records this window.</p>'}</div>
<h2>Agenda for the Product × Sales connect</h2><ol><li>What shipped and what sales can pitch now (${Rel.filter(r => /shipped|ready/i.test(r.status)).length})</li><li>Blocked features and the account impact</li><li>Accounts asking for dates: ${R.clients.filter(c => /risk|watch/i.test(c.health)).map(c => esc(c.name)).join(', ') || 'none'}</li><li>Owners and dates to confirm</li></ol>`;
return out('product_sales', 'product-sales-connect.html', page('PRODUCT × SALES', 'Product × Sales connect', 'Release readiness for the sales team', body));

