const DAYS = 7;
const until = new Date();
const since = new Date(until.getTime() - DAYS * 864e5);
return [{ json: {
  trigger: $input.first().json,
  windowDays: DAYS,
  since: since.toISOString(),
  until: until.toISOString(),
